package in.finseq.insurance;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.text.InputType;import android.view.*;import android.widget.*;
public class LockActivity extends FinseqActivity{
 private static final int RC_DEVICE_LOCK=7201;FrameLayout cover;EditText pin;PatternLockView pattern;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);render();autoUnlock();}
 private void render(){LinearLayout root=Ui.column(this);Ui.title(root,this,"Unlock FINSEQ CMS","Use your phone screen lock or FINSEQ PIN");
  if(SecurityStore.systemLock(this)){Button button=Ui.greenButton(this,"Use Your Screen Lock");button.setOnClickListener(new View.OnClickListener(){public void onClick(View v){deviceCredential();}});root.addView(button);}
  if(SecurityStore.hasPin(this)){pin=Ui.input(this,"Enter FINSEQ CMS PIN");pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);Button button=Ui.button(this,"Unlock with FINSEQ PIN");button.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(SecurityStore.checkPin(LockActivity.this,pin.getText().toString()))open();else Ui.toast(LockActivity.this,"Incorrect PIN");}});root.addView(pin);root.addView(button);}
  if(SecurityStore.hasPattern(this)){root.addView(Ui.text(this,"Pattern Lock",18,true));pattern=new PatternLockView(this);pattern.setListener(new PatternLockView.Listener(){public void onPattern(String value){if(SecurityStore.checkPattern(LockActivity.this,value))open();else{Ui.toast(LockActivity.this,"Incorrect pattern");pattern.reset();}}});root.addView(pattern);}
  FrameLayout frame=new FrameLayout(this);frame.setBackgroundColor(Color.rgb(8,17,29));frame.addView(Ui.scroll(this,root),new FrameLayout.LayoutParams(-1,-1));cover=new FrameLayout(this);cover.setBackgroundColor(Color.rgb(8,17,29));cover.setVisibility(View.GONE);frame.addView(cover,new FrameLayout.LayoutParams(-1,-1));setContentView(frame);
 }
 private void autoUnlock(){if(SecurityStore.systemLock(this)||SecurityStore.biometric(this))deviceCredential();}
 private void deviceCredential(){KeyguardManager km=(KeyguardManager)getSystemService(KEYGUARD_SERVICE);if(km==null||!km.isDeviceSecure()){SecurityStore.systemLock(this,false);Ui.toast(this,"Phone screen lock is not configured. Set it in Android Settings.");return;}Intent prompt=km.createConfirmDeviceCredentialIntent("Unlock FINSEQ CMS","Use your phone PIN, pattern or password");if(prompt==null){Ui.toast(this,"Android screen lock is unavailable");return;}cover.setVisibility(View.VISIBLE);try{startActivityForResult(prompt,RC_DEVICE_LOCK);}catch(Exception error){cover.setVisibility(View.GONE);Ui.toast(this,"Android could not open the screen-lock prompt");}}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==RC_DEVICE_LOCK){if(result==RESULT_OK)open();else cover.setVisibility(View.GONE);}}
 private void open(){if(SecurityStore.systemLock(this)){cover.setVisibility(View.VISIBLE);DeviceAuth.onUnlock(this);return;}startActivity(new Intent(this,Session.loggedIn(this)?MainActivity.class:LoginActivity.class));finish();}
 void signInFailed(String message,boolean loginRequired){cover.setVisibility(View.GONE);if(loginRequired){new AlertDialog.Builder(this).setTitle("Reconnect screen lock sign-in").setMessage(message).setPositiveButton("Staff login",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){startActivity(new Intent(LockActivity.this,LoginActivity.class));finish();}}).setNegativeButton("Retry screen lock",null).show();}else Ui.toast(this,message);}
 @Override public void onBackPressed(){moveTaskToBack(true);}
}
